CREATE OR REPLACE FUNCTION private.assert_application_price_v5(n needs, p_covered_slots integer, p_price_rsd integer)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if p_price_rsd is null or p_price_rsd <= 0 then
    raise exception using errcode='22023', message='INVALID_PRICE';
  end if;

  if n.mode = 'MY_PRICE' then
    if n.requester_price_rsd is null or n.requester_price_rsd <= 0 then
      raise exception using errcode='P0001', message='FIXED_PRICE_NOT_READY';
    end if;

    if n.price_basis is null then
      if p_price_rsd <> n.requester_price_rsd then
        raise exception using errcode='22023', message='FIXED_PRICE_MISMATCH';
      end if;
    elsif n.price_basis = 'PER_PERSON' then
      if p_price_rsd <> n.requester_price_rsd::bigint * p_covered_slots then
        raise exception using
          errcode='22023',
          message='FIXED_PRICE_MISMATCH',
          detail=format('basis=PER_PERSON,perPerson=%s,covered=%s,expected=%s,sent=%s',
                        n.requester_price_rsd, p_covered_slots,
                        n.requester_price_rsd::bigint * p_covered_slots, p_price_rsd);
      end if;
    elsif n.price_basis = 'TOTAL' then
      if p_price_rsd::numeric is distinct from
         round(n.requester_price_rsd::numeric * p_covered_slots / n.required_slots) then
        raise exception using errcode='22023', message='FIXED_PRICE_MISMATCH',
          detail=format('basis=TOTAL,total=%s,required=%s,covered=%s,sent=%s',
            n.requester_price_rsd,n.required_slots,p_covered_slots,p_price_rsd);
      end if;
    elsif n.price_basis = 'HOURLY' then
      -- R07b: an hourly amount is one person's rate for one hour.
      -- Headcount and duration remain independent accepted facts.
      if p_price_rsd <> n.requester_price_rsd then
        raise exception using errcode='22023', message='FIXED_PRICE_MISMATCH';
      end if;
    else
      raise exception using errcode='22023', message='UNKNOWN_PRICE_BASIS';
    end if;
  end if;

end;
$function$

CREATE OR REPLACE FUNCTION private.match_detail_for_calendar_interval(nid uuid, pid uuid, s timestamp with time zone, e timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare result jsonb; blockers jsonb;
begin
  if (s is null)<>(e is null) or (s is not null and (not isfinite(s) or not isfinite(e) or s>=e)) then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  result:=private.match_detail_without_calendar(nid,pid);
  if result is null or not private.worker_calendar_conflict(pid,s,e,null) then return result; end if;
  blockers:=coalesce(result->'hardBlockers','[]'::jsonb);
  if not (blockers @> '["CALENDAR_CONFLICT"]'::jsonb) then blockers:=blockers||'["CALENDAR_CONFLICT"]'::jsonb; end if;
  result:=jsonb_set(result,'{hardBlockers}',blockers,true);
  result:=jsonb_set(result,'{responseAllowed}','false'::jsonb,true);
  return jsonb_set(result,'{dispatchEligible}','false'::jsonb,true);
end;
$function$

CREATE OR REPLACE FUNCTION private.push_suppression(p_delivery notification_deliveries)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  p public.notification_preferences%rowtype;
  e public.user_activity_events%rowtype;
  enabled boolean;
  local_time time;
begin
  if p_delivery.channel<>'PUSH' or p_delivery.state in ('SUPPRESSED','EXPIRED','READ','DELIVERED','FAILED_FINAL') then
    return 'DELIVERY_CLOSED';
  end if;
  if p_delivery.expires_at<=clock_timestamp() then
    return 'EXPIRED';
  end if;
  select * into e from public.user_activity_events where id=p_delivery.event_id;
  if not found or e.recipient_user_id<>p_delivery.recipient_user_id or e.recipient_role<>p_delivery.recipient_role then
    return 'EVENT_UNAVAILABLE';
  end if;

  select * into p from public.notification_preferences where user_id=p_delivery.recipient_user_id and role_context=p_delivery.recipient_role;
  if not found then
    -- When preferences row does not exist yet, default all categories and push to ON
    return null;
  end if;

  if not coalesce(p.push_enabled, true) then
    return 'PUSH_OFF';
  end if;

  enabled:=case private.category_of_event(e.event_type)
    when 'opportunities' then coalesce(p.opportunities_enabled, true)
    when 'responses' then coalesce(p.responses_enabled, true)
    when 'dogovor' then coalesce(p.dogovor_enabled, true)
    when 'execution' then coalesce(p.execution_enabled, true)
    when 'recovery' then coalesce(p.recovery_enabled, true)
    else coalesce(p.account_enabled, true)
  end;
  if not enabled then
    return 'CATEGORY_OFF';
  end if;

  local_time:=(clock_timestamp() at time zone coalesce(p.quiet_timezone, 'UTC'))::time;
  if coalesce(p.quiet_hours_enabled, false)
     and (case when p.quiet_start<p.quiet_end then local_time between p.quiet_start and p.quiet_end else local_time>=p.quiet_start or local_time<=p.quiet_end end)
     and not(e.urgency='HITNO' and coalesce(p.urgent_overrides_quiet_hours, true)) then
    return 'QUIET_HOURS';
  end if;

  return null;
end $function$

CREATE OR REPLACE FUNCTION private.safety_event_blocked(e user_activity_events)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.agreements; peer uuid; target uuid;
begin
 -- Safe terminal notification must not make an active Agreement inescapable.
 if e.event_type in('AGREEMENT_CANCELLED','NEED_CANCELLED','EXECUTION_STATE_CHANGED','COMPLETION_REQUIRED','RECOVERY_OPENED') then return false; end if;
 if e.entity_type='AGREEMENT' then
  select * into a from public.agreements where id=e.entity_id;
  peer:=case when e.recipient_user_id=a.requester_account_id then a.worker_account_id when e.recipient_user_id=a.worker_account_id then a.requester_account_id end;
 elsif e.entity_type='RESPONSE' then
  select case when e.recipient_user_id=r.worker_account_id then n.requester_account_id
   when e.recipient_user_id=n.requester_account_id then r.worker_account_id end into peer
   from public.marketplace_responses r join public.needs n on n.id=r.need_id where r.id=e.entity_id;
 elsif e.entity_type='NEED' then
  select requester_account_id into peer from public.needs where id=e.entity_id;
 elsif e.entity_type='CLARIFICATION' then
  select case when e.recipient_user_id=n.requester_account_id then qa.asker_account_id else n.requester_account_id end into peer
   from private.preselection_qa_questions qa join public.needs n on n.id=qa.need_id where qa.id=e.entity_id;
 end if;
 if peer is null or peer=e.recipient_user_id then return false; end if;
 perform pg_advisory_xact_lock_shared(private.safety_pair_key(e.recipient_user_id,peer));
 return private.safety_pair_blocked(e.recipient_user_id,peer);
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_claim_push_transport(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare d public.notification_deliveries%rowtype; a public.notification_push_attempts%rowtype; v_now timestamptz:=clock_timestamp(); why text; dev record; num integer; paused_recipients uuid[]:=array[]::uuid[];
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_kind is null or p_kind not in ('SEND','RECEIPT') then raise exception 'INVALID_PUSH_ACTION' using errcode='22023'; end if;
 -- Cross-isolate dispatch throttle and SKIP LOCKED delivery ownership. No
 -- in-memory limit is mistaken for a project-wide limiter.
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:push-claim',0)) then return jsonb_build_object('kind','WAIT','retryAfterMs',100); end if;
 if (select count(*) from public.notification_push_attempts where lease_until>v_now)>=6 then return jsonb_build_object('kind','WAIT','retryAfterMs',250); end if;
 if (select count(*) from public.notification_push_attempts where last_claimed_at>v_now-interval '1 second')>=60 then return jsonb_build_object('kind','WAIT','retryAfterMs',1000); end if;
 -- Only the already rate-bounded last second is examined. Limit any one
 -- recipient to four claims/second across devices; receipts count too and
 -- can only defer, never discard, a later send. The global advisory lock
 -- serializes the check plus lease, including other Edge isolates.
 if p_kind='SEND' then
  select coalesce(array_agg(q.recipient_user_id),array[]::uuid[]) into paused_recipients
  from (select d1.recipient_user_id
    from public.notification_push_attempts a1
    join public.notification_deliveries d1 on d1.id=a1.delivery_id
    where a1.last_claimed_at>v_now-interval '1 second'
    group by d1.recipient_user_id having count(*)>=4) q;
 end if;
 for d in select * from public.notification_deliveries x where x.channel='PUSH'
  and (p_kind<>'SEND' or not(x.recipient_user_id=any(paused_recipients))) and not exists(select 1 from public.notification_push_attempts admitted where admitted.delivery_id=x.id and admitted.single_target_admission is not null) and
  ((p_kind='SEND' and x.push_started_at is null and x.state in ('CREATED','QUEUED','FAILED_RETRYABLE') and not exists(select 1 from public.notification_push_attempts z where z.delivery_id=x.id))
   or exists(select 1 from public.notification_push_attempts z where z.delivery_id=x.id and
    ((p_kind='SEND' and z.transport_state in ('PENDING','RETRYABLE','SEND_LEASED','SEND_STARTED')) or (p_kind='RECEIPT' and z.transport_state in ('TICKET_PENDING','RECEIPT_LEASED')))
    and (z.next_attempt_at<=v_now or z.lease_until<=v_now)))
  -- HIGH receives a one-minute ordering advantage. Older normal work then
  -- overtakes newer HIGH arrivals, so a sustained burst cannot starve it.
  order by x.created_at-case when x.priority='HIGH' then interval '1 minute' else interval '0 seconds' end,x.created_at,x.id limit 64 for update skip locked loop
  if d.push_started_at is null and p_kind='SEND' then
   why:=private.push_suppression(d);
   if why is not null then update public.notification_deliveries set state='SUPPRESSED',suppression_reason=why,push_started_at=v_now where id=d.id; continue; end if;
   -- Historical attempts are not reinterpreted or resent by the new transport.
   if exists(select 1 from public.notification_push_attempts where delivery_id=d.id) then continue; end if;
   num:=0;
   for dev in select * from public.notification_push_devices x where x.user_id=d.recipient_user_id and x.active and x.bound_revision=x.revision and private.push_session_valid(x.user_id,x.bound_session_id) and x.platform in ('IOS','ANDROID') order by x.id loop
    num:=num+1;
    insert into public.notification_push_attempts(delivery_id,device_id,attempt_no,outcome,transport_state,device_revision,next_attempt_at)
    values(d.id,dev.id,num,'QUEUED','PENDING',dev.revision,v_now);
   end loop;
   update public.notification_deliveries set push_started_at=v_now,queued_at=v_now,state=case when num=0 then 'SUPPRESSED' else 'QUEUED' end,suppression_reason=case when num=0 then 'NO_ACTIVE_DEVICE' else null end where id=d.id;
  end if;
  -- Losing a worker after begin may have produced a real push. Never resend it.
  update public.notification_push_attempts set transport_state='UNKNOWN',outcome='FATAL',error_code='SEND_OUTCOME_UNKNOWN',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='SEND_STARTED' and lease_until<=v_now;
  update public.notification_push_attempts set transport_state='PENDING',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='SEND_LEASED' and lease_until<=v_now;
  update public.notification_push_attempts set transport_state='TICKET_PENDING',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='RECEIPT_LEASED' and lease_until<=v_now;
  update public.notification_push_attempts set transport_state='UNKNOWN',outcome='FATAL',error_code='RECEIPT_UNAVAILABLE',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='TICKET_PENDING' and ticket_received_at<=v_now-interval '24 hours';
  select * into a from public.notification_push_attempts where delivery_id=d.id and next_attempt_at<=v_now and
   ((p_kind='SEND' and transport_state in ('PENDING','RETRYABLE') and send_count<3) or (p_kind='RECEIPT' and transport_state='TICKET_PENDING')) order by attempt_no limit 1 for update;
  if not found then continue; end if;
  if p_kind='SEND' then
   why:=private.push_suppression(d);
   if why is not null then update public.notification_push_attempts set transport_state='SUPPRESSED',outcome='FATAL',error_code=why where id=a.id; continue; end if;
   select * into dev from public.notification_push_devices x where x.id=a.device_id and x.user_id=d.recipient_user_id and x.active and x.revision=a.device_revision and x.bound_revision=x.revision and private.push_session_valid(x.user_id,x.bound_session_id);
   if not found then update public.notification_push_attempts set transport_state='SUPPRESSED',outcome='FATAL',error_code='DEVICE_CHANGED' where id=a.id; continue; end if;
  end if;
  update public.notification_push_attempts set transport_state=case when p_kind='SEND' then 'SEND_LEASED' else 'RECEIPT_LEASED' end,lease_id=extensions.gen_random_uuid(),lease_until=v_now+interval '90 seconds',next_attempt_at=v_now,last_claimed_at=v_now where id=a.id returning * into a;
  return jsonb_build_object('kind',p_kind,'attemptId',a.id,'leaseId',a.lease_id,'leaseExpiresAt',a.lease_until,'ticketId',a.provider_ticket_id);
 end loop;
 if p_kind='SEND' and cardinality(paused_recipients)>0 then
  return jsonb_build_object('kind','WAIT','retryAfterMs',1000);
 end if;
 return jsonb_build_object('kind','NONE');
end $function$

CREATE OR REPLACE FUNCTION public.rpc_complete_push_transport(p_attempt_id uuid, p_lease_id uuid, p_result text, p_ticket_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.notification_push_attempts%rowtype; d public.notification_deliveries%rowtype; token text; receipt boolean; v_now timestamptz:=clock_timestamp(); next_state text;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_result is null or p_result not in ('TICKET','PROVIDER_ACCEPTED','DEVICE_NOT_REGISTERED','RETRYABLE','RECEIPT_RATE_EXCEEDED','FATAL','UNKNOWN','RECEIPT_PENDING') or
  (p_result='TICKET' and (p_ticket_id is null or p_ticket_id!~'^[A-Za-z0-9_-]{1,200}$')) or (p_result<>'TICKET' and p_ticket_id is not null) then raise exception 'INVALID_PUSH_RESULT' using errcode='22023'; end if;
 select x.expo_push_token into token from public.notification_push_devices x join public.notification_push_attempts y on y.device_id=x.id where y.id=p_attempt_id;
 if token is not null then perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||token,0)); end if;
 select x.* into d from public.notification_deliveries x join public.notification_push_attempts y on y.delivery_id=x.id where y.id=p_attempt_id for update of x;
 select * into a from public.notification_push_attempts where id=p_attempt_id for update;
 if not found or a.lease_id is distinct from p_lease_id or a.lease_until<=clock_timestamp() or a.transport_state not in ('SEND_STARTED','RECEIPT_LEASED') then raise exception 'PUSH_LEASE_STALE' using errcode='PT409'; end if;
 receipt:=a.transport_state='RECEIPT_LEASED';
 if (receipt and (p_result='TICKET' or a.provider_ticket_id is null)) or (not receipt and p_result in ('PROVIDER_ACCEPTED','RECEIPT_PENDING','RECEIPT_RATE_EXCEEDED'))
 or (p_result='TICKET' and p_ticket_id=any(a.rejected_ticket_ids)) then raise exception 'INVALID_PUSH_RESULT' using errcode='22023'; end if;
 -- A documented receipt MessageRateExceeded is a known rejection of this
 -- message, unlike HTTP429 while merely looking up a receipt. Only the former
 -- permits a new send, with current-device/consent revalidation and max3 sends.
 next_state:=case p_result when 'TICKET' then 'TICKET_PENDING' when 'PROVIDER_ACCEPTED' then 'PROVIDER_ACCEPTED' when 'DEVICE_NOT_REGISTERED' then 'FINAL' when 'UNKNOWN' then 'UNKNOWN' when 'RECEIPT_PENDING' then 'TICKET_PENDING' when 'RECEIPT_RATE_EXCEEDED' then case when a.send_count<3 then 'RETRYABLE' else 'FINAL' end when 'RETRYABLE' then case when receipt then 'TICKET_PENDING' when a.send_count<3 then 'RETRYABLE' else 'FINAL' end else 'FINAL' end;
 -- A one-shot admission never regains send permission, including known provider throttles.
 if a.single_target_admission is not null and next_state='RETRYABLE' then next_state:='FINAL'; end if;
 update public.notification_push_attempts set transport_state=next_state,
  outcome=case when next_state='PROVIDER_ACCEPTED' then 'OK' when next_state='RETRYABLE' then 'RETRYABLE' when next_state in ('TICKET_PENDING') then 'QUEUED' else 'FATAL' end,
  error_code=case when p_result in ('TICKET','PROVIDER_ACCEPTED') then null else p_result end,
  rejected_ticket_ids=case when p_result='RECEIPT_RATE_EXCEEDED' and next_state='RETRYABLE' then array_append(rejected_ticket_ids,provider_ticket_id) else rejected_ticket_ids end,
  provider_ticket_id=case when p_result='TICKET' then p_ticket_id when p_result='RECEIPT_RATE_EXCEEDED' and next_state='RETRYABLE' then null else provider_ticket_id end,
  ticket_received_at=case when p_result='TICKET' then v_now when p_result='RECEIPT_RATE_EXCEEDED' and next_state='RETRYABLE' then null else ticket_received_at end,
  receipt_checked_at=case when receipt then v_now else receipt_checked_at end,
  next_attempt_at=case when next_state='TICKET_PENDING' then v_now+interval '15 minutes' when next_state='RETRYABLE' then v_now+make_interval(secs=>power(2,a.send_count)::integer*30) else null end,
  lease_id=null,lease_until=null where id=a.id;
 if p_result='DEVICE_NOT_REGISTERED' then
  -- Token rebind / revoke / re-registration changes revision. An old provider
  -- result must never disable a different user's or a newer registration.
  update public.notification_push_devices set active=false,revision=revision+1,bound_session_id=null,bound_revision=null
  where id=a.device_id and user_id=d.recipient_user_id and revision=a.device_revision and active;
 end if;
 if p_result='TICKET' and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE') then update public.notification_deliveries set state='SENT',sent_at=coalesce(sent_at,v_now) where id=d.id; end if;
 -- DELIVERED and delivered_at are deliberately never written by this adapter.
 return jsonb_build_object('attemptId',a.id,'state',next_state);
end $function$

CREATE OR REPLACE FUNCTION public.rpc_submit_response(p_need_id uuid, p_need_revision integer, p_worker_profile_id uuid, p_covered_slots integer, p_price_rsd integer, p_proposed_start_at timestamp with time zone, p_proposed_end_at timestamp with time zone, p_scope_note text, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  n public.needs;
  v_profile public.app_profiles;
  v_resp public.marketplace_responses;
  v_command private.response_submit_commands;
  v_match jsonb;
  v_content_hash text;
  v_request_hash text;
  v_result jsonb;
  v_version integer;
  v_selected_slots integer := 0;
  v_remaining_slots integer := 0;
begin
  if u is null then
    raise exception using errcode='42501', message='AUTH_REQUIRED';
  end if;

  if p_client_request_id is null
     or char_length(btrim(p_client_request_id)) not between 8 and 200 then
    raise exception using errcode='22023', message='INVALID_CLIENT_REQUEST_ID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(u::text || ':' || p_client_request_id, 7241)
  );

  -- Bind only the semantic client command. Server-derived profile/Need snapshot
  -- intentionally does not enter the request hash, so a retry after a committed
  -- response replays the exact first result even if current context later moves.
  v_request_hash := encode(sha256(convert_to(jsonb_build_object(
    'needId', p_need_id,
    'needRevision', p_need_revision,
    'workerProfileId', p_worker_profile_id,
    'coveredSlots', p_covered_slots,
    'priceRsd', p_price_rsd,
    'proposedStartAt', p_proposed_start_at,
    'proposedEndAt', p_proposed_end_at,
    'scopeNote', coalesce(p_scope_note, '')
  )::text, 'UTF8')), 'hex');

  select * into v_command
    from private.response_submit_commands c
   where c.worker_account_id = u
     and c.client_request_id = p_client_request_id;

  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception using errcode='22023', message='IDEMPOTENCY_KEY_REUSED';
    end if;
    return v_command.result || jsonb_build_object('idempotentReplay', true);
  end if;

  -- Shared mutation lock order remains Need first.
  select * into n
    from public.needs
   where id = p_need_id
   for update;

  if not found then
    raise exception using errcode='P0002', message='NEED_NOT_FOUND';
  end if;

  if not private.accounts_same_world(n.requester_account_id, u) then
    raise exception using errcode='P0002', message='NEED_NOT_FOUND';
  end if;

  select * into v_command
    from private.response_submit_commands c
   where c.worker_account_id = u
     and c.client_request_id = p_client_request_id
   for update;

  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception using errcode='22023', message='IDEMPOTENCY_KEY_REUSED';
    end if;
    return v_command.result || jsonb_build_object('idempotentReplay', true);
  end if;

  if n.status not in ('PUBLISHED','SELECTION') then
    raise exception using errcode='22023', message='NEED_NOT_OPEN';
  end if;

  if n.requester_account_id = u then
    raise exception using errcode='42501', message='OWN_NEED';
  end if;

  if n.response_deadline is not null
     and n.response_deadline <= statement_timestamp() then
    raise exception using errcode='22023', message='RESPONSE_WINDOW_EXPIRED';
  end if;

  -- New work uses the same actual task-time boundary as search/dispatch.
  -- Replay already returned above; evaluate after the Need lock was acquired.
  if not private.need_search_time_admitted_v1(n.id,clock_timestamp()) then
    raise exception 'NEED_EXECUTION_WINDOW_EXPIRED' using errcode='PT409',
      hint='Vreme za ovaj zadatak je isteklo.';
  end if;

  if n.revision is distinct from p_need_revision then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  -- Lock the current Worker profile after the Need. ACTIVE alone is not enough
  -- for legacy rows: P0C-02 rechecks the exact RU-1 minimum readiness facts.
  select * into v_profile
    from public.app_profiles p
   where p.id = p_worker_profile_id
   for update;

  if not found
     or v_profile.account_id <> u
     or v_profile.kind <> 'WORKER' then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if v_profile.profile_status <> 'ACTIVE'
     or char_length(btrim(v_profile.display_name)) < 2
     or (char_length(btrim(v_profile.city)) < 2 and private.worker_remote_only_activation_ready_v1(v_profile.account_id,v_profile.skills) IS NOT TRUE)
     or cardinality(v_profile.skills) < 1 then
    raise exception using errcode='P0001', message='WORKER_PROFILE_NOT_READY';
  end if;

  select coalesce(sum(s.covered_slots), 0)::integer
    into v_selected_slots
    from public.need_selections s
   where s.need_id = n.id
     and s.status = 'SELECTED';

  v_remaining_slots := greatest(0, n.required_slots - v_selected_slots);

  if v_remaining_slots < 1 then
    raise exception using errcode='P0001', message='NEED_FULL';
  end if;

  if p_covered_slots is null or p_covered_slots < 1 then
    raise exception using errcode='22023', message='INVALID_COVERED_SLOTS';
  end if;

  -- WPP01: people are committed per offer; the personal profile is not a team limit.
  -- Existing remaining-slot and pricing checks below remain authoritative.

  if p_covered_slots > v_remaining_slots then
    raise exception using
      errcode='22023',
      message='NEED_REMAINING_CAPACITY_EXCEEDED',
      detail=format('covered=%s,remaining=%s', p_covered_slots, v_remaining_slots);
  end if;

  perform private.assert_application_price_v5(n, p_covered_slots, p_price_rsd);

  if (p_proposed_start_at is null) <> (p_proposed_end_at is null)
     or (
       p_proposed_start_at is not null
       and p_proposed_end_at is not null
       and p_proposed_start_at >= p_proposed_end_at
     ) then
    raise exception using errcode='22023', message='INVALID_PROPOSED_INTERVAL';
  end if;

  if exists (
    select 1
      from public.marketplace_responses r
     where r.need_id = p_need_id
       and r.worker_account_id = u
       and (
         r.status = 'SELECTED'
         or exists (
           select 1
             from public.agreements a
            where a.selected_response_id = r.id
              and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED')
         )
       )
  ) then
    raise exception using errcode='P0001', message='RESPONSE_ALREADY_SELECTED';
  end if;

  if p_proposed_start_at is null and n.schedule_kind='FIXED_WINDOW'
    and (n.starts_at is null or not isfinite(n.starts_at)
      or (n.ends_at is not null and (not isfinite(n.ends_at) or n.starts_at>=n.ends_at))) then
    raise exception 'NEED_FIXED_INTERVAL_INVALID' using errcode='22023';
  end if;
  -- Start-only appointment cannot accept a new offer after its start while lifecycle tick catches up.
  if n.schedule_kind='FIXED_WINDOW' and n.ends_at is null
     and n.starts_at is not null and n.starts_at<=statement_timestamp() then
    raise exception 'FIXED_WINDOW_START_PASSED' using errcode='22023';
  end if;
  v_match := private.match_detail_for_calendar_interval(p_need_id, p_worker_profile_id,
    coalesce(p_proposed_start_at,case when n.schedule_kind='FIXED_WINDOW' and n.ends_at is not null then n.starts_at end),
    coalesce(p_proposed_end_at,case when n.schedule_kind='FIXED_WINDOW' and n.ends_at is not null then n.ends_at end));
  if not coalesce((v_match->>'responseAllowed')::boolean, false) then
    raise exception using
      errcode='P0001',
      message='WORKER_NOT_ELIGIBLE',
      detail=coalesce((v_match->'hardBlockers')::text, '[]');
  end if;

  select * into v_resp
    from public.marketplace_responses r
   where r.need_id = p_need_id
     and r.worker_account_id = u
     and r.status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')
   order by r.created_at desc
   limit 1
   for update;

  -- Content identity includes the server-derived self-declared capability/team
  -- snapshot. It is not public trust/verification and is never copied into the
  -- global public profile DTO.
  v_content_hash := encode(sha256(convert_to(jsonb_build_object(
    'needRevision', n.revision,
    'pricingMode', n.mode,
    'applicationPriceBasis', (case when n.mode='MY_PRICE' and n.price_basis='HOURLY' then 'HOURLY' else 'TOTAL' end),
    'currency', 'RSD',
    'priceRsd', p_price_rsd,
    'coveredSlots', p_covered_slots,
    'proposedStartAt', p_proposed_start_at,
    'proposedEndAt', p_proposed_end_at,
    'scopeNote', coalesce(btrim(p_scope_note), ''),
    'snapshotSchema', 'APPLICATION_V1_SELF_DECLARED',
    'workerTeamCapacity', v_profile.team_capacity,
    'workerSkills', to_jsonb(v_profile.skills),
    'workerTools', '[]'::jsonb,
    'workerLicenses', to_jsonb(v_profile.licenses),
    'workerVehicles', '[]'::jsonb
  )::text, 'UTF8')), 'hex');

  if v_resp.id is null then
    insert into public.marketplace_responses (
      need_id, worker_account_id, worker_profile_id, response_kind, status,
      submitted_against_need_revision, current_version, covered_slots,
      price_rsd, price_basis, proposed_start_at, proposed_end_at, scope_note, submitted_at
    ) values (
      p_need_id, u, p_worker_profile_id, 'OFFER', 'SUBMITTED', n.revision, 1,
      p_covered_slots, p_price_rsd, (case when n.mode='MY_PRICE' and n.price_basis='HOURLY' then 'HOURLY' else 'TOTAL' end), p_proposed_start_at, p_proposed_end_at,
      coalesce(p_scope_note, ''), statement_timestamp()
    )
    returning * into v_resp;
    v_version := 1;
  else
    v_version := v_resp.current_version + 1;
    update public.marketplace_responses
       set current_version = v_version,
           status = 'SUBMITTED',
           submitted_against_need_revision = n.revision,
           covered_slots = p_covered_slots,
           price_rsd = p_price_rsd,
           price_basis = (case when n.mode='MY_PRICE' and n.price_basis='HOURLY' then 'HOURLY' else 'TOTAL' end),
           proposed_start_at = p_proposed_start_at,
           proposed_end_at = p_proposed_end_at,
           scope_note = coalesce(p_scope_note, ''),
           submitted_at = statement_timestamp(),
           withdrawn_at = null
     where id = v_resp.id
     returning * into v_resp;
  end if;

  insert into public.marketplace_response_versions (
    response_id, version, need_revision, covered_slots, price_rsd, price_basis,
    proposed_start_at, proposed_end_at, scope_note, content_hash
  ) values (
    v_resp.id, v_version, n.revision, p_covered_slots, p_price_rsd, (case when n.mode='MY_PRICE' and n.price_basis='HOURLY' then 'HOURLY' else 'TOTAL' end),
    p_proposed_start_at, p_proposed_end_at, coalesce(p_scope_note, ''),
    v_content_hash
  );

  insert into private.response_application_snapshots (
    response_id, response_version, snapshot_schema,
    worker_profile_id, worker_team_capacity, covered_slots,
    need_required_slots, need_selected_slots_before_submit,
    need_remaining_slots_before_submit, pricing_mode, requester_price_rsd,
    worker_skills, worker_tools, worker_licenses, worker_vehicles
  ) values (
    v_resp.id, v_version, 'APPLICATION_V1_SELF_DECLARED',
    v_profile.id, v_profile.team_capacity, p_covered_slots,
    n.required_slots, v_selected_slots, v_remaining_slots,
    n.mode, n.requester_price_rsd,
    v_profile.skills, '{}'::text[], v_profile.licenses, '{}'::text[]
  );

  update public.opportunity_deliveries
     set status = 'RESPONDED',
         responded_at = statement_timestamp()
   where need_id = p_need_id
     and need_revision = n.revision
     and worker_account_id = u
     and status in ('READY','SEEN');

  v_result := jsonb_build_object(
    'responseId', v_resp.id,
    'applicationId', v_resp.id,
    'version', v_version,
    'needRevision', n.revision,
    'contentHash', v_content_hash,
    'status', v_resp.status,
    'pricingMode', n.mode,
    'applicationPriceBasis', (case when n.mode='MY_PRICE' and n.price_basis='HOURLY' then 'HOURLY' else 'TOTAL' end),
    'currency', 'RSD',
    'coveredSlots', p_covered_slots,
    'priceRsd', p_price_rsd,
    'snapshotSchema', 'APPLICATION_V1_SELF_DECLARED',
    'authoritative', true,
    'idempotentReplay', false
  );

  insert into private.response_submit_commands (
    worker_account_id, client_request_id, request_hash,
    response_id, response_version, result
  ) values (
    u, p_client_request_id, v_request_hash,
    v_resp.id, v_version, v_result
  );

  -- PRE-V3: persisted version trigger owns Application semantic events.

  return v_result;
end;
